"""The ``stockroom`` command."""

import csv
import io
import json
import os
import sys

from ._text import ORDER_RE, SKU_RE, parse_date, parse_uint
from .errors import ParseError, clip
from .orders import (plan_shipment, report_rows, shipped_order, shipped_so_far,
                     status as order_status)
from .parsing import Movement, parse_catalog, parse_movements, parse_orders
from .pricing import fmt, price_order
from .shelves import check_stock, history, low_stock, stock_levels, status

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"

# command -> (positional argument counts, flag options, files to read)
SHELVES = (CATALOG, MOVEMENTS)
COMMANDS = {
    "stock": ((0,), ("--json",), SHELVES),
    "low": ((0,), ("--json",), SHELVES),
    "history": ((1,), ("--json",), SHELVES),
    "receive": ((3, 4), (), SHELVES),
    "ship": ((3, 4), (), SHELVES),
    "quote": ((1,), ("--json",), (CATALOG, ORDERS)),
    "fulfil": ((2,), (), (CATALOG, MOVEMENTS, ORDERS)),
    "invoice": ((1,), ("--json",), (CATALOG, MOVEMENTS, ORDERS)),
    "report": ((0,), (), (CATALOG, MOVEMENTS, ORDERS)),
}
RAW_ARGS = ("receive", "ship", "fulfil")
FORMATS = ("text", "csv", "json")


class Fail(Exception):
    def __init__(self, code, message):
        message = clip(message)
        super().__init__(message)
        self.code = code
        self.message = message


def _is_option(arg):
    return arg.startswith("--") or (
        len(arg) > 1 and arg[0] == "-" and arg[1] in
        "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")


def _parse_args(argv):
    """Check the command line; return (command, dir, positionals, options)."""
    directory = "."
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise Fail(2, "option --dir needs a value")
            directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            directory = arg[len("--dir="):]
        else:
            rest.append(arg)
        i += 1
    if directory == "":
        raise Fail(2, "option --dir needs a value")
    if not rest:
        raise Fail(2, "no command given")
    command = rest[0]
    if command not in COMMANDS:
        raise Fail(2, "unknown command %r" % command)
    counts, flags, _ = COMMANDS[command]
    args = rest[1:]
    options = {}
    positional = []
    if command in RAW_ARGS:
        positional = args
    else:
        i = 0
        while i < len(args):
            arg = args[i]
            if arg in flags:
                options[arg] = True
            elif command == "report" and arg == "--format":
                if i + 1 >= len(args):
                    raise Fail(2, "option --format needs a value")
                options["--format"] = args[i + 1]
                i += 1
            elif command == "report" and arg.startswith("--format="):
                options["--format"] = arg[len("--format="):]
            elif _is_option(arg):
                raise Fail(2, "unknown option %r" % arg)
            else:
                positional.append(arg)
            i += 1
        if command == "report":
            fmt_name = options.setdefault("--format", "text")
            if fmt_name not in FORMATS:
                raise Fail(2, "bad value %r for --format" % fmt_name)
    if len(positional) not in counts:
        raise Fail(2, "wrong number of arguments for %s" % command)
    if command in ("receive", "ship") and parse_date(positional[0]) is None:
        raise Fail(2, "bad date %r" % positional[0])
    if command == "fulfil" and parse_date(positional[1]) is None:
        raise Fail(2, "bad date %r" % positional[1])
    return command, directory, positional, options


def _read(directory, name, required):
    try:
        with open(os.path.join(directory, name), "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise Fail(2, "%s: file not found" % name)
        return ""
    except OSError as err:
        raise Fail(2, "%s: %s" % (name, err.strerror or err))
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise Fail(2, "%s: not valid UTF-8" % name)


def _parsed(name, func, *args):
    try:
        return func(*args)
    except ParseError as err:
        raise Fail(1, "%s: %s" % (name, err))


class _Books:
    """The files a command reads, parsed in catalogue, movements, orders order."""

    def __init__(self, directory, files):
        if not os.path.isdir(directory):
            raise Fail(2, "%s: not a directory" % directory)
        self.directory = directory
        self.catalog = _parsed(CATALOG, parse_catalog,
                               _read(directory, CATALOG, True))
        self.movements_text = ""
        self.movements = []
        self.orders = []
        if MOVEMENTS in files:
            self.movements_text = _read(directory, MOVEMENTS, False)
            self.movements = _parsed(MOVEMENTS, parse_movements,
                                     self.movements_text, self.catalog)
        if ORDERS in files:
            self.orders = _parsed(ORDERS, parse_orders,
                                  _read(directory, ORDERS, False), self.catalog)

    def append_movements(self, new):
        """Validate the whole file plus ``new``, then append it in one write."""
        text = self.movements_text
        prefix = "\n" if text and not text.endswith("\n") else ""
        number = text.count("\n") + len(prefix) + 1
        added = []
        for i, move in enumerate(new):
            added.append(Movement(move.date, move.sku, move.quantity,
                                  move.note, number + i))
        try:
            check_stock(self.movements + added)
        except ParseError as err:
            raise Fail(1, "%s: %s" % (MOVEMENTS, err))
        lines = [_movement_text(m) for m in added]
        try:
            payload = (prefix + "".join(l + "\n" for l in lines)).encode("utf-8")
        except UnicodeEncodeError:
            raise Fail(1, "note cannot be written as UTF-8")
        try:
            with open(os.path.join(self.directory, MOVEMENTS), "ab") as handle:
                handle.write(payload)
        except OSError as err:
            raise Fail(2, "%s: %s" % (MOVEMENTS, err.strerror or err))
        return lines

    def find_order(self, text):
        if ORDER_RE.fullmatch(text):
            for order in self.orders:
                if order.id == text.upper():
                    return order
        raise Fail(1, "unknown order %r" % text)


def _movement_text(move):
    text = "%s %s %+d" % (move.date.isoformat(), move.sku, move.quantity)
    return text + " " + move.note if move.note else text


def _json(value):
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def _lines(rows):
    return "".join(row + "\n" for row in rows)


def _cmd_stock(books, args, options):
    levels = stock_levels(books.catalog, books.movements)
    rows = []
    for sku in sorted(books.catalog):
        product = books.catalog[sku]
        rows.append((sku, product.name, levels[sku],
                     status(levels[sku], product.reorder)))
    if options.get("--json"):
        return _json([{"sku": s, "name": n, "onhand": o, "status": st}
                      for s, n, o, st in rows])
    return _lines("%s %d %s %s" % (s, o, st, n) for s, n, o, st in rows)


def _cmd_low(books, args, options):
    rows = low_stock(books.catalog, books.movements)
    if options.get("--json"):
        return _json([{"sku": p.sku, "onhand": o, "reorder": p.reorder, "buy": b}
                      for p, o, b in rows])
    return _lines("%s %d %d %d" % (p.sku, o, p.reorder, b) for p, o, b in rows)


def _cmd_history(books, args, options):
    text = args[0]
    if not SKU_RE.fullmatch(text) or text.upper() not in books.catalog:
        raise Fail(1, "unknown SKU %r" % text)
    rows = history(text.upper(), books.movements)
    if options.get("--json"):
        return _json([{"date": m.date.isoformat(), "delta": "%+d" % m.quantity,
                       "balance": b, "note": m.note} for m, b in rows])
    return _lines(
        "%s %+d %d%s" % (m.date.isoformat(), m.quantity, b,
                         " " + m.note if m.note else "") for m, b in rows)


def _cmd_move(sign):
    def run(books, args, options):
        date_text, sku_text, qty_text = args[:3]
        note = args[3] if len(args) == 4 else ""
        if not SKU_RE.fullmatch(sku_text) or sku_text.upper() not in books.catalog:
            raise Fail(1, "unknown SKU %r" % sku_text)
        quantity = parse_uint(qty_text)
        if quantity is None or quantity < 1:
            raise Fail(1, "bad quantity %r" % qty_text)
        if "\n" in note or "\r" in note:
            raise Fail(1, "a note may not contain a line break")
        move = Movement(parse_date(date_text), sku_text.upper(), sign * quantity,
                        note.strip())
        return _lines(books.append_movements([move]))
    return run


def _quote_dict(quote):
    return {
        "order": quote.order,
        "date": quote.date.isoformat(),
        "customer": quote.customer,
        "lines": [{"sku": l.sku, "quantity": l.quantity, "unit": fmt(l.unit),
                   "gross": fmt(l.gross), "discount": fmt(l.discount),
                   "net": fmt(l.net)} for l in quote.lines],
        "subtotal": fmt(quote.subtotal),
        "order_discount": fmt(quote.order_discount),
        "tax": fmt(quote.tax),
        "total": fmt(quote.total),
    }


def _quote_text(quote, prefix=""):
    rows = ["%s%s %s %s" % (prefix, quote.order, quote.date.isoformat(),
                            quote.customer)]
    for l in quote.lines:
        rows.append("%s %d %s %s %s %s" % (l.sku, l.quantity, fmt(l.unit),
                                          fmt(l.gross), fmt(l.discount),
                                          fmt(l.net)))
    rows.append("subtotal " + fmt(quote.subtotal))
    rows.append("order discount " + fmt(quote.order_discount))
    rows.append("tax " + fmt(quote.tax))
    rows.append("total " + fmt(quote.total))
    return _lines(rows)


def _cmd_quote(books, args, options):
    quote = price_order(books.find_order(args[0]), books.catalog)
    if options.get("--json"):
        return _json(_quote_dict(quote))
    return _quote_text(quote)


def _cmd_invoice(books, args, options):
    order = books.find_order(args[0])
    sent = shipped_order(order, shipped_so_far(order, books.movements))
    if not sent.lines:
        raise Fail(1, "nothing shipped for %s" % order.id)
    quote = price_order(sent, books.catalog)
    if options.get("--json"):
        return _json(_quote_dict(quote))
    return _quote_text(quote, "invoice ")


def _cmd_fulfil(books, args, options):
    order = books.find_order(args[0])
    date = parse_date(args[1])
    if date < order.date:
        raise Fail(1, "%s is dated %s, before the order" % (date, order.date))
    before = shipped_so_far(order, books.movements)
    plan = plan_shipment(order, date, books.movements)
    new = [Movement(date, sku, -n, "order " + order.id)
           for sku, n in plan if n > 0]
    if new:
        books.append_movements(new)
    after = [(sku, sent + n) for (sku, sent), (_, n) in zip(before, plan)]
    rows = []
    for (sku, qty), (_, n), (_, total) in zip(order.lines, plan, after):
        rows.append("%s shipped %d backordered %d" % (sku, n, qty - total))
    rows.append("status " + order_status(order, after))
    return _lines(rows)


def _cmd_report(books, args, options):
    rows = report_rows(books.orders, books.catalog, books.movements)
    kind = options["--format"]
    if kind == "json":
        return _json([dict(r, date=r["date"], quoted=fmt(r["quoted"]),
                           invoiced=fmt(r["invoiced"])) for r in rows])
    if kind == "csv":
        out = io.StringIO()
        writer = csv.writer(out, lineterminator="\n")
        writer.writerow(["order", "date", "customer", "status", "ordered",
                         "shipped", "quoted", "invoiced"])
        for r in rows:
            writer.writerow([r["order"], r["date"], r["customer"], r["status"],
                             r["ordered"], r["shipped"], fmt(r["quoted"]),
                             fmt(r["invoiced"])])
        return out.getvalue()
    return _lines("%s %s %s %s %d/%d %s %s" % (
        r["order"], r["date"], r["customer"], r["status"], r["shipped"],
        r["ordered"], fmt(r["quoted"]), fmt(r["invoiced"])) for r in rows)


HANDLERS = {
    "stock": _cmd_stock, "low": _cmd_low, "history": _cmd_history,
    "receive": _cmd_move(1), "ship": _cmd_move(-1), "quote": _cmd_quote,
    "fulfil": _cmd_fulfil, "invoice": _cmd_invoice, "report": _cmd_report,
}


def _run(argv):
    command, directory, args, options = _parse_args(argv)
    books = _Books(directory, COMMANDS[command][2])
    return HANDLERS[command](books, args, options)


def _quiet_stdout():
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def _emit(text):
    out = sys.stdout
    try:
        if hasattr(out, "buffer"):
            out.buffer.write(text.encode("utf-8"))
        else:
            out.write(text)
        out.flush()
    except BrokenPipeError:
        _quiet_stdout()
        return 0
    except OSError as err:
        _quiet_stdout()
        _say("cannot write output: %s" % (err.strerror or err))
        return 2
    return 0


def _say(message):
    try:
        sys.stderr.write("stockroom: %s\n" % message)
        sys.stderr.flush()
    except (OSError, ValueError):
        pass


def main(argv=None):
    """Run the command; returns the exit status (0, 1 or 2)."""
    argv = list(sys.argv[1:] if argv is None else argv)
    try:
        text = _run(argv)
    except Fail as err:
        _say(err.message)
        return err.code
    return _emit(text)


if __name__ == "__main__":
    sys.exit(main())

