        raise Fail(1, "unknown SKU %r" % text)
    rows = history(text.upper(), books.movements)
    if options.get("--json"):
        return _json([{"date": m.date.isoformat(), "delta": "%+d" % m.quantity,
                       "balance": b, "note": m.note} for m, b in rows])
    return _lines(
        "%s %+d %d%s" % (m.date.isoformat(), m.quantity, b,
                         " " + m.note if m.note else "") for m, b in rows)


def _cmd_move(sign):
    def run(books, args, options):
        date_text, sku_text, qty_text = args[:3]
        note = args[3] if len(args) == 4 else ""
        if not SKU_RE.fullmatch(sku_text) or sku_text.upper() not in books.catalog:
            raise Fail(1, "unknown SKU %r" % sku_text)
        quantity = parse_uint(qty_text)
        if quantity is None or quantity < 1:
            raise Fail(1, "bad quantity %r" % qty_text)
        if "\n" in note or "\r" in note:
            raise Fail(1, "a note may not contain a line break")
        move = Movement(parse_date(date_text), sku_text.upper(), sign * quantity,
                        note.strip())
        return _lines(books.append_movements([move]))
    return run


